/**
 * Revenue aggregation and customer loyalty classification (Topological Level 2).
 */

import { compute_invoice_net_total } from "./invoice";

import { compute_final_price } from "./pricing";

import { round_currency } from "./tax_rules";

export function aggregate_revenue(revenues: Array<number>): number {
  let total = 0.0;
  for (const rev of revenues) {
    if ((rev > 0.0)) {
      total += rev;
    }
  }
  return round_currency(total, 2);
}

export function average_order_value(revenues: Array<number>): number {
  let valid = revenues.filter((r) => (r > 0.0)).map((r) => r);
  if ((valid.length === 0)) {
    return 0.0;
  }
  return round_currency((valid.reduce((acc: number, val: number) => acc + val, 0) / valid.length), 2);
}

export function classify_customer_tier(annual_spend: number): string {
  if ((annual_spend >= 5000.0)) {
    return "platinum";
  }
  if ((annual_spend >= 1500.0)) {
    return "gold";
  }
  if ((annual_spend >= 500.0)) {
    return "silver";
  }
  return "standard";
}

export function simulate_regional_campaign(gross_amounts: Array<number>, tier: string, coupon_code: string, region: string): number {
  let campaign_total = 0.0;
  for (const amt of gross_amounts) {
    campaign_total += compute_final_price(amt, tier, coupon_code, region);
  }
  let bonus_invoice = compute_invoice_net_total(gross_amounts, tier, region);
  return round_currency(((campaign_total + bonus_invoice) / 2.0), 2);
}
